from dataclasses import dataclass, replace

@dataclass(frozen=True)
class Punkt:
    x: int
    y: int

p = Punkt(1, 2)
# p.x = 5 → FrozenInstanceError
q = replace(p, x=5)
print(p, q)
# Punkt(x=1, y=2) Punkt(x=5, y=2)

// C#: record Punkt(int X, int Y);
// var q = p with { X = 5 };

